import {
  Mjml,
  MjmlBody,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlSection,
  MjmlWrapper,
  MjmlSpacer,
  MjmlText,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type FullWidthImage_FullWidthImageVariant =
  | "default"
  | "top-padding"
  | "top-right"
  | "top-left"
  | "top-sides"
  | "right-padding"
  | "right-alt"
  | "bottom-padding"
  | "bottom-right"
  | "bottom-left"
  | "bottom-sides"
  | "left-padding"
  | "left-alt"
  | "sides-padding"
  | "sides-alt";

interface FullWidthImage_FullWidthImageProps {
  theme?: EmailTheme;
  imageSrc?: string;
  imageAlt?: string;
  pageBackgroundColor?: string;
  spacerBackgroundColor?: string;
  variant?: FullWidthImage_FullWidthImageVariant;
}

const FullWidthImage_variantPadding: Record<
  FullWidthImage_FullWidthImageVariant,
  string
> = {
  "bottom-left": "0 0 24px 24px",
  "bottom-padding": "0 0 24px",
  "bottom-right": "0 24px 24px 0",
  "bottom-sides": "0 24px 24px",
  default: "0",
  "left-alt": "0 0 0 24px",
  "left-padding": "0 0 0 24px",
  "right-alt": "0 24px 0 0",
  "right-padding": "0 24px 0 0",
  "sides-alt": "0 24px",
  "sides-padding": "0 24px",
  "top-left": "24px 0 0 24px",
  "top-padding": "24px 0 0",
  "top-right": "24px 24px 0 0",
  "top-sides": "24px 24px 0",
};

const FullWidthImage_FullWidthImageSection = ({
  imageSrc = emailAsset("image-grids/full-width.jpg"),
  imageAlt = "",
  spacerBackgroundColor = "#fffffe",
  variant = "default",
}: Omit<FullWidthImage_FullWidthImageProps, "theme">) => (
  <MjmlSection
    backgroundColor={spacerBackgroundColor}
    padding={FullWidthImage_variantPadding[variant]}
  >
    <MjmlColumn padding="0">
      <MjmlImage alt={imageAlt} padding="0" src={imageSrc} width="600px" />
    </MjmlColumn>
  </MjmlSection>
);

const FullWidthImage_FullWidthImage = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "default",
  ...props
}: FullWidthImage_FullWidthImageProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Full width image</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">
        <FullWidthImage_FullWidthImageSection {...props} variant={variant} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

FullWidthImage_FullWidthImage.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies FullWidthImage_FullWidthImageProps;

const __FullWidthImage = FullWidthImage_FullWidthImage;

type FullWidthOverlay_FullWidthImageWithOverlayVariant =
  | "default"
  | "top-padding"
  | "top-right"
  | "top-left"
  | "top-sides"
  | "right-padding"
  | "right-alt"
  | "bottom-padding"
  | "bottom-right"
  | "bottom-left"
  | "bottom-sides"
  | "left-padding"
  | "left-alt"
  | "sides-padding"
  | "sides-alt";

interface FullWidthOverlay_FullWidthImageWithOverlayProps {
  theme?: EmailTheme;
  imageSrc?: string;
  heading?: string;
  subtext?: string;
  headingColor?: string;
  textColor?: string;
  pageBackgroundColor?: string;
  spacerBackgroundColor?: string;
  variant?: FullWidthOverlay_FullWidthImageWithOverlayVariant;
}

const FullWidthOverlay_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const FullWidthOverlay_variantPadding: Record<
  FullWidthOverlay_FullWidthImageWithOverlayVariant,
  string
> = {
  "bottom-left": "0 0 24px 24px",
  "bottom-padding": "0 0 24px",
  "bottom-right": "0 24px 24px 0",
  "bottom-sides": "0 24px 24px",
  default: "0",
  "left-alt": "0 0 0 24px",
  "left-padding": "0 0 0 24px",
  "right-alt": "0 24px 0 0",
  "right-padding": "0 24px 0 0",
  "sides-alt": "0 24px",
  "sides-padding": "0 24px",
  "top-left": "24px 0 0 24px",
  "top-padding": "24px 0 0",
  "top-right": "24px 24px 0 0",
  "top-sides": "24px 24px 0",
};

const FullWidthOverlay_FullWidthImageWithOverlaySection = ({
  imageSrc = emailAsset("image-grids/full-width-2.jpg"),
  heading = "Nike",
  subtext = "Shoes and accessories",
  headingColor = "#fffffe",
  textColor = "#fffffe",
  spacerBackgroundColor = "#fffffe",
  variant = "default",
}: Omit<FullWidthOverlay_FullWidthImageWithOverlayProps, "theme">) => (
  <MjmlWrapper
    backgroundColor={spacerBackgroundColor}
    padding={FullWidthOverlay_variantPadding[variant]}
  >
    <MjmlSection
      backgroundColor="#000001"
      backgroundUrl={imageSrc}
      backgroundPosition="center"
      backgroundRepeat="no-repeat"
      backgroundSize="cover"
      padding="0"
    >
      <MjmlColumn padding="0" verticalAlign="bottom">
        <MjmlSpacer height="292px" />
        <MjmlText
          color={headingColor}
          fontFamily={FullWidthOverlay_fontFamily}
          fontSize="24px"
          fontWeight="700"
          lineHeight="32px"
          padding="16px 16px 0"
        >
          {heading}
        </MjmlText>
        <MjmlText
          color={textColor}
          fontFamily={FullWidthOverlay_fontFamily}
          fontSize="20px"
          lineHeight="28px"
          padding="0 16px 16px"
        >
          {subtext}
        </MjmlText>
      </MjmlColumn>
    </MjmlSection>
  </MjmlWrapper>
);

const FullWidthOverlay_FullWidthImageWithOverlay = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "default",
  ...props
}: FullWidthOverlay_FullWidthImageWithOverlayProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{props.heading ?? "Nike"}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <FullWidthOverlay_FullWidthImageWithOverlaySection
        {...props}
        variant={variant}
      />
    </MjmlBody>
  </Mjml>
);

FullWidthOverlay_FullWidthImageWithOverlay.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies FullWidthOverlay_FullWidthImageWithOverlayProps;

const __FullWidthOverlay = FullWidthOverlay_FullWidthImageWithOverlay;

export interface GalleryImage {
  src: string;
  alt?: string;
  href?: string;
  heading?: string;
  subtext?: string;
}

export interface FullWidthImageProps {
  theme?: Parameters<typeof __FullWidthImage>[0]["theme"];
  image?: GalleryImage;
  overlay?: boolean;
  frame?: "none" | "top" | "right" | "bottom" | "left" | "sides";
  frameStyle?: "padding" | "split" | "alternate" | "sides";
}

const fullWidthVariant = ({
  frame,
  frameStyle,
}: Required<Pick<FullWidthImageProps, "frame" | "frameStyle">>) => {
  if (frame === "none") {
    return "default" as const;
  }
  if (frameStyle === "padding") {
    return `${frame}-padding` as const;
  }
  if (frameStyle === "sides" && (frame === "top" || frame === "bottom")) {
    return `${frame}-sides` as const;
  }
  if (frame === "top" || frame === "bottom") {
    return `${frame}-${frameStyle === "alternate" ? "right" : "left"}` as const;
  }
  return `${frame}-${frameStyle === "alternate" ? "alt" : "padding"}` as const;
};

export const FullWidthImage = ({
  theme,
  image,
  overlay = false,
  frame = "none",
  frameStyle = "padding",
}: FullWidthImageProps) => {
  const variant = fullWidthVariant({ frame, frameStyle });
  return overlay ? (
    <__FullWidthOverlay
      heading={image?.heading}
      imageSrc={image?.src}
      subtext={image?.subtext}
      theme={theme}
      variant={variant}
    />
  ) : (
    <__FullWidthImage
      imageAlt={image?.alt}
      imageSrc={image?.src}
      theme={theme}
      variant={variant}
    />
  );
};

FullWidthImage.PreviewProps = {
  frame: "none",
  frameStyle: "padding",
  overlay: false,
} satisfies FullWidthImageProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
